_PFX = {"NZD": "NZ$", "AUD": "A$", "USD": "US$"}


def format_money(amount, currency):
    if currency not in _PFX:
        raise ValueError("unknown currency")
    a = _r(Decimal(str(amount)))
    sign = "-" if a < 0 else ""
    return sign + _PFX[currency] + "{:,.2f}".format(abs(a))
